/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Can_Lut_Sw_Status can_lut_sw_insert_id_ext (Can_Lut_Sw * const can_lut_sw , Can_Dev_Id const dev_id , UInt32 const id , const Can_Lut_Sw_Index_Func index_func)
{
  Can_Lut_Sw_Entry entry ;

  entry.def.dev_id           = dev_id      ;
  entry.def.type             = CAN_LUT_EXT ;
  entry.def.ident.single.val = id          ;
  entry.index_func           = index_func  ;

  return can_lut_sw_insert_entry (can_lut_sw , & entry) ;
}

